namespace winrt::ReactNativeWebViewWindows::implementation
{
    // ------------------------------------------------------------------------
    // JS availability probe. Auto-registered by ReactPackageProvider's
    // AddAttributedModules(builder, true) purely because this translation unit
    // is compiled+linked (same TU as the component => the probe can never
    // disagree with component presence). The JS side gates on
    // NativeModules.RNCWebViewWindowsInfo?.isAvailable?.() and falls back to a
    // placeholder when absent or false (old binaries receiving OTA JS, or
    // old-arch hosts).
    // ------------------------------------------------------------------------
    REACT_MODULE(WebViewInfoModule, L"RNCWebViewWindowsInfo");
    struct WebViewInfoModule
    {
        REACT_SYNC_METHOD(isAvailable);
        bool isAvailable() noexcept
        {
#ifdef RNW_NEW_ARCH
            return true;
#else
            return false;
#endif
        }
    };
}
